local _, WFJ = ...
WFJ.Data.add("book", {
  ["201e6c3920159a23"] = { "<HTML>\n<BODY>\n<H1 align=\"center\">\nCapitolo 2: IL PILASTRO ORIENTALE\n</H1>\n<BR/>\n<BR/>\n<IMG src=\"Interface\\Pictures\\11482_crystals_mini_east\" align=\"left\"/>\n<P align=\"right\">Il pilastro<BR/>\norientale<BR/>\naccetta cristalli<BR/>\nblu, gialli<BR/>\ne verdi.</P>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align=\"left\">Il pilastro si concentra sull'energia che si può creare usando i cristalli blu come fonte principale di potere.</P>\n</BODY>\n</HTML>", "." },
  ["2084ed277722c33c"] = { "Ho finalmente scovato qualche informazione sull'ex soldato che hai combattuto. La pista era difficile da seguire, perché questo albero genealogico non era stato documentato a dovere, ma alla fine ho trovato un consanguineo.\n\nCi crederesti che il custode Alen, alla ⟦Light's Hope Chapel=Cappella della Luce⟧, è in realtà il figlio di Christoph? Sapere qualcosa di suo padre potrebbe dargli pace. Se mai ti ritroverai di nuovo al servizio dell'⟦Argent Dawn=Alba d'Argento⟧ nelle ⟦Plaguelands=Terre Infette⟧, ti prego, parlagli. Sarebbe un gesto gentile.", "." },
  ["20afc939e19b9b33"] = { "Col tempo, entità demoniache si fecero strada nei mondi dei Titani dalla ⟦Twisting Nether=Distorsione Fatua⟧, e il Pantheon elesse il suo più grande guerriero, Sargeras, come prima linea di difesa. Nobile gigante di bronzo fuso, Sargeras svolse il suo compito per innumerevoli millenni, cercando e distruggendo quei demoni ovunque riuscisse a trovarli. Nel corso delle ere, Sargeras incontrò due potenti razze demoniache, entrambe decise a conquistare potere e dominio sull'universo fisico.", "." },
  ["20c20f67849753aa"] = { "La furiosa cacofonia nella sua mente rese Ner'zhul ancora più potente, come se quegli spiriti gli fornissero un nutrimento di cui aveva gran bisogno. Scoprì che era un gioco da ragazzi controllare le azioni degli zombi e guidarli verso qualunque fine desiderasse.", "." },
  ["20f17fa45d1ac5fe"] = { "MOR GRAYHOOF, continua...\n\nIn seguito scoprimmo che Mor era sopravvissuto alla caduta. Ma per il mio caro amico non ci sarebbe stato un lieto fine: fu fatto prigioniero dai troll di Tazz'Alaor. Poco dopo, mentre il maestro di guerra Voone lo torturava, un gruppo di assassini di Valthalak irruppe e finì il lavoro.\n\nSe intendi richiamare l'eco dello spirito di Mor Grayhoof, la sala del maestro di guerra Voone è un luogo infestato.", "." },
  ["20f904cfbbb2f4b9"] = { "Persino la forma titanica di Sargeras si deformò per la corruzione che affliggeva il suo cuore un tempo nobile. Occhi, capelli e barba eruppero in fiamme, e la sua pelle di bronzo metallico si squarciò, rivelando una fornace senza fine di odio rovente.", "." },
})
